import type { GapListResponse, ResearchGap } from "./types";

export function listGaps(params?: {
  run_id?: number;
  limit?: number;
  offset?: number;
  search?: string;
  gap_type?: string;
  min_confidence?: number;
  sort_by?: string;
  sort_order?: string;
}): Promise<GapListResponse> {
